<?php
$page_title="Hasil voting";include "_header.php";?>
<div class="row g-3"><?php foreach(['Kakang','Senduk'] as $cat):?><div class="col-lg-6"><div class="panel p-3 p-md-4"><h5 class="admin-title">Hasil <?=e($cat)?></h5><?php $s=$conn->prepare("SELECT k.nama,COALESCE(SUM(v.jumlah_suara),0) suara FROM kontestan k LEFT JOIN voting v ON v.kontestan_id=k.id WHERE k.kategori=? GROUP BY k.id ORDER BY suara DESC");$s->bind_param("s",$cat);$s->execute();$rs=$s->get_result();$grand=0;$arr=$rs->fetch_all(MYSQLI_ASSOC);foreach($arr as $x)$grand+=$x['suara'];foreach($arr as $x):$pct=$grand?round($x['suara']/$grand*100,1):0;?><div class="mb-3"><div class="d-flex justify-content-between"><strong><?=e($x['nama'])?></strong><span><?=$x['suara']?> suara (<?=$pct?>%)</span></div><div class="progress mt-2"><div class="progress-bar" style="width:<?=$pct?>%"></div></div></div><?php endforeach;?><div class="small-muted">Total suara sah: <?=$grand?></div></div></div><?php endforeach;?></div>
<?php include "_footer.php"; ?>